import{c as a,$ as l,Q as r,j as e,g as o,o as n,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const x=JSON.parse('{"title":"ПРО: Мультипространства и Личные финансы","description":"Управление несколькими бизнесами в одной программе, единый бэкап и автоматическая консолидация личных трат.","frontmatter":{"title":"ПРО: Мультипространства и Личные финансы","description":"Управление несколькими бизнесами в одной программе, единый бэкап и автоматическая консолидация личных трат.","order":15,"datePublished":"2026-08-20","dateModified":"2026-11-07"},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/pro-mode.md","filePath":"ru/docs/spaces/moy-kapital/pro-mode.md","lastUpdated":1794009600000}'),c={name:"ru/docs/spaces/moy-kapital/pro-mode.md"},p={id:"про-режим-экосистема-для-масштабирования",tabindex:"-1"};function g(m,t,h,u,f,b){const s=l("DocIcon");return r(),e("div",null,[o("h1",p,[n(s,{name:"pro"}),t[0]||(t[0]=i(" ПРО-режим: Экосистема для масштабирования ",-1)),t[1]||(t[1]=o("a",{class:"header-anchor",href:"#про-режим-экосистема-для-масштабирования","aria-label":'Permalink to "ПРО-режим: Экосистема для масштабирования"'},"​",-1))]),t[2]||(t[2]=d('<p><strong>ПРО-режим</strong> — это премиум-архитектура ОмниКрафт ЕРП, которая превращает локальную программу из инструмента учёта одной мастерской в полноценную <strong>экосистему управления капиталом</strong>.</p><p>Этот режим открывает две ключевые возможности:</p><ol><li><strong>Мультипространства:</strong> Ведение нескольких независимых бизнесов с изолированными базами данных.</li><li><strong>Глобальная вкладка «Мой капитал»:</strong> Автоматический учёт личных финансов через математическую дельту, без необходимости вбивать каждый чек за кофе.</li></ol><div class="info custom-block"><p class="custom-block-title">Как активировать ПРО?</p><p>ПРО-режим активируется флагом в вашем лицензионном ключе. Как только ключ с типом <code>Про</code> вводится во вкладке «Настройки», программа мгновенно разблокирует выдвижную боковую панель и глобальные инструменты консолидации.</p></div><hr><h2 id="мультипространства" tabindex="-1">Мультипространства <a class="header-anchor" href="#мультипространства" aria-label="Permalink to &quot;Мультипространства&quot;">​</a></h2><p>Многие ремесленники со временем запускают смежные направления: основная кожевенная мастерская, продажа электронных лекал, преподавание на курсах или ремонт изделий. Смешивать всё это в одной базе — плохая идея: разные валюты, разные наценки, разный склад и абсолютно разная экономика.</p><p>ПРО-режим позволяет создавать <strong>неограниченное количество изолированных рабочих пространств</strong>. Каждое пространство — это полноценная, отдельная рабочая база со своими справочниками, рецептами, складом и историей продаж.</p><h3 id="как-это-работает-боковая-шторка" tabindex="-1">Как это работает (Боковая шторка) <a class="header-anchor" href="#как-это-работает-боковая-шторка" aria-label="Permalink to &quot;Как это работает (Боковая шторка)&quot;">​</a></h3><p>В верхней правой части окна появляется кнопка <strong>«Пространства и Модули»</strong>. При нажатии на неё выезжает правая боковая шторка, которая становится вашим главным диспетчерским пультом.</p><p>В верхней секции шторки отображается список всех созданных вами пространств:</p><ul><li>🟢 <strong>Зелёная иконка:</strong> Текущее активное пространство, данные которого вы сейчас видите на экране.</li><li>⚪ <strong>Серая иконка:</strong> Другие зарегистрированные базы. Нажмите на них, чтобы мгновенно переключиться.</li></ul><p>При переключении программа на лету подменяет путь к активной базе данных. Интерфейс (вкладки Мастерской, Калькулятора, ДДС и т.д.) мгновенно перезагружается, подтягивая цифры, остатки и аналитику выбранного бизнеса.</p><h3 id="создание-нового-пространства" tabindex="-1">Создание нового пространства <a class="header-anchor" href="#создание-нового-пространства" aria-label="Permalink to &quot;Создание нового пространства&quot;">​</a></h3><p>Внизу списка находится кнопка <strong>«Добавить пространство»</strong>. При нажатии открывается диалог, где вы вводите понятное имя (например, <em>«Выкройки и ПДФ»</em> или <em>«Кожевенный ремонт»</em>).</p><p>Программа автоматически:</p><ol><li>Генерирует числовой идентификатор и создаёт новый физический файл базы данных в защищённой системной папке.</li><li>Инициализирует в нём все необходимые таблицы (Склад, Верстак, ДДС, Капитал и т.д.).</li><li>Регистрирует пространство в глобальном реестре <code>workspaces.json</code>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Изоляция данных</p><p>Пространства полностью независимы. У каждого бизнеса своя ставка мастера, своя глобальная наценка, свои статьи накладных расходов и свой склад сырья. Вы можете вести один бизнес в рублях, а второй — в долларах или евро, просто измени валюту учёта в настройках конкретного пространства.</p></div><hr><h2 id="единыи-глобальныи-бэкап" tabindex="-1">Единый глобальный бэкап <a class="header-anchor" href="#единыи-глобальныи-бэкап" aria-label="Permalink to &quot;Единый глобальный бэкап&quot;">​</a></h2><p>В ПРО-режиме система резервного копирования эволюционирует. Вместо того чтобы экспортировать каждую базу данных по отдельности, программа упаковывает <strong>абсолютно всё</strong> в один сжатый архив:</p><ul><li>🗃️ Реестр пространств (<code>workspaces.json</code>).</li><li>📦 Базу данных по умолчанию (<code>omnicraft_erp.db</code>).</li><li>📁 Всю папку <code>workspaces/</code> со всеми дополнительными бизнесами.</li><li>💳 Глобальную базу личных финансов (<code>personal_finance.db</code>).</li></ul><p>Это означает, что для полного переноса вашей экосистемы на новый компьютер или для создания страховочной копии вам достаточно сделать <strong>один клик</strong> в меню <code>Файл ➔ Экспорт данных</code>.</p><hr><h2 id="глобальная-вкладка-«мои-капитал»-личные-финансы" tabindex="-1">Глобальная вкладка «Мой капитал» (Личные финансы) <a class="header-anchor" href="#глобальная-вкладка-«мои-капитал»-личные-финансы" aria-label="Permalink to &quot;Глобальная вкладка «Мой капитал» (Личные финансы)&quot;">​</a></h2><p>Эта функция решает ключевую задачу предпринимателя: <strong>как учитывать личные деньги без ручного ввода каждого чека и мелких расходов?</strong></p><p>В ПРО-режиме в боковой шторке появляется крупная кнопка <strong>«Мой капитал»</strong>. При её нажатии стандартные бизнес-вкладки скрываются, и открывается глобальная консолидация, выстроенная в виде удобной 5-вкладочной воронки:</p><h3 id="_1-счета-и-инвестиции-ликвидныи-контур" tabindex="-1">1. Счета и инвестиции (Ликвидный контур) <a class="header-anchor" href="#_1-счета-и-инвестиции-ликвидныи-контур" aria-label="Permalink to &quot;1. Счета и инвестиции (Ликвидный контур)&quot;">​</a></h3><p>Единый центр управления ликвидностью вне бизнеса, объединённый компактным сегментным переключателем:</p><ul><li><strong>Счета и кошельки:</strong> дебетовые и кредитные карты, наличные средства в кошельках, накопительные счета, вклады и депозиты, валютные активы и расчётные стейблкоины (USDT, USDC). Диалог создания счета оснащен сегментированным переключателем режимов: <strong>«Одиночный счет»</strong> (лаконичная форма для независимых счетов и наличных) и <strong>«Группа / Банк / Хранилище»</strong> (мультивалютный контейнер с динамическим добавлением любого числа позиций через кнопку <strong>«Добавить еще валюту / счет в группу»</strong>). Счета с одинаковым именем группы (например, «Основной банк», «Сбережения», «Электронный кошелек») автоматически объединяются в наглядные сводные мультивалютные карточки с расчётом общего баланса в базовой валюте, бейджем количества позиций, кнопкой быстрого переименования группы и добавлением новых валют прямо из карточки. Для счетов в отличной от базовой валюте задаётся курс пересчёта, гарантирующий точный расчёт совокупного капитала. Тип счёта по умолчанию создаётся со статусом «Без категории», а группы категорий снабжены едиными лаконичными иконками для визуальной строгости.</li><li><strong>Архив и безопасное удаление счетов:</strong> неактуальные счета отправляются в архив кнопкой «В архив» на карточке счёта. Группы автоматически исчезают из активного списка, если все входящие в них счета перенесены в архив. Режим архива открывается кнопкой-тумблером на панели инструментов: из архива счёт можно вернуть в активный учёт или безвозвратно удалить из системы.</li><li><strong>Инвестиционный портфель:</strong> учёт ценных бумаг (акции, облигации, фонды), долей в бизнесе, криптовалютных активов и выданных займов с автоматическим расчётом финансового результата (P&amp;L = Текущая стоимость − Вложенный капитал) и процентной доходности с учётом валютной переоценки. Архитектура портфеля опирается на строгую 3-уровневую иерархию: <strong>«Класс активов (Категория групп) → Площадка / Брокер (Группа) → Финансовые инструменты (Счета и позиции)»</strong>. В шапке расположена мультисегментная полоса распределения капитала (<strong>Allocation Bar</strong>) с интерактивной легендой. Доли владения в процентах наглядно выводятся на каждом уровне: доля класса активов в заголовке категории, доля брокера/площадки в портфеле и доля инструмента в совокупном капитале (с фиксацией веса внутри группы). Доступно переключение видов (<strong>«Полосы»</strong> для плотного просмотра и <strong>«Плитка»</strong> для блочной сетки без англицизмов), глобальное сворачивание/разворачивание групп кнопкой <code>↕</code>, точечное упорядочивание позиций стрелками ↑ / ↓, а также быстрое добавление актива прямо в группу кнопкой <code>+</code>. По кнопке редактирования группы открывается полноценное окно управления площадкой: переименование с каскадным обновлением связанных инструментов, смена класса активов, инлайн-редактирование и удаление позиций, а также ручное упорядочивание порядка отображения. Модальное окно создания инвестиций полностью унифицировано с окном счетов: двухсегментный переключатель между <strong>«Одиночным активом»</strong> и <strong>«Группой / Брокером / Площадкой»</strong> позволяет вносить как разовые инструменты, так и пакетом формировать целый портфель брокера с динамическим добавлением позиций, индивидуальными валютами, курсами и спойлерами параметров.</li><li><strong>Фиксация сделок и архив инвестиций:</strong> для корректного закрытия позиции используется кнопка <strong>«Зафиксировать сделку / Продать»</strong>. В появившемся окне указывается сумма продажи, дата выхода и комментарий. Система вычисляет и замораживает реализованный финансовый результат (P&amp;L = Сумма продажи − Вложенный капитал), перемещая позицию в архив. Это исключает искажение статистики и сохраняет накопленную прибыль. При необходимости сделку можно вернуть в открытый портфель.</li><li><strong>Интеллектуальный страж (умная защита):</strong> если при стандартном редактировании актива мастер случайно указывает остаток <code>0</code> или уменьшает текущую стоимость более чем на 95%, программа предотвращает слепое списание и открывает диалог подтверждения намерения: зафиксировать продажу или отразить реальную просадку актива. При удалении актива в корзину система также предлагает зафиксировать сделку с сохранением финансового результата вместо безвозвратного удаления.</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Где учитывать стейблкоины и криптовалюту?</p><p>Расчётные стейблкоины (USDT, USDC) и криптовалютные кошельки, используемые как платёжное средство или резерв ликвидности, учитываются во вкладке <strong>«Счета и кошельки»</strong> с фиксацией курса к базовой валюте. Вкладка <strong>«Инвестиционный портфель»</strong> предназначена для активов с расчётом доходности, дивидендов и прироста тела капитала (акции, облигации, волатильная криптовалюта, доли в бизнесах, займы).</p></div><h3 id="_2-имущество-и-материалы-единыи-материальныи-реестр" tabindex="-1">2. Имущество и материалы (Единый материальный реестр) <a class="header-anchor" href="#_2-имущество-и-материалы-единыи-материальныи-реестр" aria-label="Permalink to &quot;2. Имущество и материалы (Единый материальный реестр)&quot;">​</a></h3><p>Центральный реестр всех материальных активов мастера с 4 ключевыми карточками сводки (<code>Все имущество и материалы</code>, <code>Недвижимость и авто</code>, <code>Оборудование и станки</code>, <code>Сырьё и запасы</code>) и 4-сегментным фильтром:</p><ul><li><strong>Недвижимость и автомобили:</strong> личные квартиры, земля, рабочий и персональный транспорт, ценные вещи с возможностью постановки финансовых целей накопления.</li><li><strong>Оборудование и станки:</strong> парки машин, станки, инструменты мастерских с динамической амортизацией и точной настройкой долей владения.</li><li><strong>Материалы и запасы:</strong> складские остатки сырья, фурнитуры и расходных материалов по скользящей средней (метод скользящей средней МАК) со всех зарегистрированных складов.</li><li><strong>Доли владения (3-сторонний баланс Гамильтона):</strong> иконка диаграммы открывает редактор распределения актива между контурами: Личное + Производство + Услуги = 100,00% (10 000 б.п.) с мгновенной автоматической балансировкой остатков.</li><li><strong>Защитные барьеры удаления (интеллектуальный страж целостности):</strong> кнопка удаления автоматически проверяет наличие операционной истории через инспектора связей (проводки движения денег в ДДС, списания сырья со склада, производственные партии, амортизационные начисления и ремонты). Если объект участвовал в реальной работе, прямое стирание блокируется диалогом <strong>«Удаление заблокировано: есть история»</strong>. Программа выводит перечень найденных зависимостей и перенаправляет операцию в безопасное выбытие в Архив с обязательным указанием причины: <ul><li><em>«Продано / реализовано»</em> — вывод актива с фиксацией выручки;</li><li><em>«Сломано / утилизировано по износу»</em> — плановое или аварийное списание выработавшего ресурс инструмента;</li><li><em>«Подарено / выведено из эксплуатации»</em> — безвозмездная передача или консервация. Нажатие кнопки <strong>«Отправить в архив»</strong> исключает позицию из рабочих реестров, сохраняя финансовую точность баланса и непрерывность кассовых отчетов.</li></ul></li><li><strong>Инспектор дубликатов и коллизий:</strong> аудит задвоенных карточек и расхождений в сумме долей владения.</li></ul><h3 id="_3-важные-операции" tabindex="-1">3. Важные операции <a class="header-anchor" href="#_3-важные-операции" aria-label="Permalink to &quot;3. Важные операции&quot;">​</a></h3><p>Журнал для учёта только <strong>существенных</strong> внешних потоков, которые нельзя игнорировать:</p><ul><li><em>Внешние доходы:</em> Зарплата по найму, разовый фриланс, дивиденды, крупные подарки.</li><li><em>Целевые расходы:</em> Крупные покупки, оплата обучения, медицинские услуги, погашение обязательств.</li></ul><h3 id="_4-мои-капитал-итоговая-сводка" tabindex="-1">4. Мой капитал (Итоговая сводка) <a class="header-anchor" href="#_4-мои-капитал-итоговая-сводка" aria-label="Permalink to &quot;4. Мой капитал (Итоговая сводка)&quot;">​</a></h3><p>Сердце раздела. Здесь программа сводит воедино данные всех ваших бизнес-пространств и личных счетов, рассчитывая ключевые показатели:</p><div class="tip custom-block"><p class="custom-block-title">Адаптация при первом запуске</p><p>Если личные счета и рабочие пространства ещё не сформированы, экран встречает понятной карточкой первого старта (первичное состояние экрана) с кнопкой быстрого добавления первого счёта и возможностью ознакомиться с демонстрационным режимом.</p></div><ul><li><strong>Структура совокупного капитала:</strong> сквозной 4-столпный срез: <ol><li>💳 <strong>Счета (Деньги)</strong> — ликвидные остатки на картах, счетах и в наличных.</li><li>📈 <strong>Инвестиции</strong> — акции, облигации, фонды и криптоактивы.</li><li>🏠 <strong>Личные активы</strong> — недвижимость, автомобили, ценные вещи.</li><li>🏭 <strong>Имущество пространств</strong> — совокупная стоимость станков, оборудования, транспорта и складских запасов всех мастерских.</li></ol></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Показатель</th><th style="text-align:left;">Что означает</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>💎 Абсолютный капитал (Чистые активы)</strong></td><td style="text-align:left;">Сумма всех 4 столпов капитала (Счета + Инвестиции + Личные активы + Имущество пространств). Совокупный капитал на текущий момент.</td></tr><tr><td style="text-align:left;"><strong>💰 Заработано в бизнесах</strong></td><td style="text-align:left;">Консолидированная чистая прибыль со всех рабочих пространств за всё время.</td></tr><tr><td style="text-align:left;"><strong>📈 Внешние доходы / Накоплено</strong></td><td style="text-align:left;">Сумма всех важных личных доходов, не связанных с бизнесом.</td></tr><tr><td style="text-align:left;"><strong>📊 Прибыль от инвестиций</strong></td><td style="text-align:left;">Суммарный финансовый результат (P&amp;L) инвестиционного портфеля: нереализованная прибыль по открытым активам плюс зафиксированный результат по закрытым сделкам.</td></tr><tr><td style="text-align:left;"><strong>🔍 Свободные траты на жизнь</strong></td><td style="text-align:left;">Та самая «магическая» цифра (см. ниже).</td></tr></tbody></table><h4 id="магическая-формула-свободных-трат" tabindex="-1">Магическая формула свободных трат <a class="header-anchor" href="#магическая-формула-свободных-трат" aria-label="Permalink to &quot;Магическая формула свободных трат&quot;">​</a></h4><p>Как программа узнаёт, сколько вы потратили на жизнь (еду, бензин, кофе, одежду), если вы не вбивали эти чеки? Она вычисляет их <strong>от обратного</strong>, через дельту капитала:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Финансовая модель</span><div class="formula-heading">Формула расчёта свободных трат на жизнь</div></div><div class="formula-equation-box"><div class="math-line"><span class="math-var">Свободные траты</span><span class="math-op">=</span><span class="math-calc-expr">Прибыль мастерских</span><span class="math-op">+</span><span class="math-calc-expr">Внешние доходы</span><span class="math-op">−</span><span class="math-calc-expr">Важные расходы</span><span class="math-op">−</span><span class="math-calc-expr">Прирост капитала</span></div></div><div class="formula-card-bottom"><p>Вычисляет реальные расходы на повседневную жизнь от обратного через дельту чистых активов на счетах.</p></div></div><p><strong>Как это работает на практике:</strong></p><ol><li>Программа видит, что ваш бизнес принес <code>100 000 ₽</code> чистой прибыли.</li><li>Вы получили зарплату на работе <code>50 000 ₽</code> (внесли как Внешний доход).</li><li>Вы внесли крупный платеж <code>30 000 ₽</code> (внесли как Важный расход).</li><li><em>Теоретически</em> у вас должно стать больше денег на <code>120 000 ₽</code>.</li><li>Но программа смотрит на ваши реальные банковские карты и видит, что суммарный остаток вырос только на <code>40 000 ₽</code>.</li><li><strong>Вывод:</strong> <code>80 000 ₽</code> вы незаметно потратили на повседневную жизнь. Программа честно покажет эту цифру в блоке «Свободные траты на жизнь».</li></ol><div class="tip custom-block"><p class="custom-block-title">Философия «Учёта без рутины»</p><p>Этот подход полностью избавляет вас от микроменеджмента личного бюджета. Не требуется сканировать чеки из магазина. Программа выступает в роли честного зеркала: она показывает, какой объем денег «растворяется» в быту, позволяя вам оценивать свой реальный уровень жизни и корректировать финансовые цели, опираясь на твердые математические факты.</p></div><h3 id="_5-аналитика" tabindex="-1">5. Аналитика <a class="header-anchor" href="#_5-аналитика" aria-label="Permalink to &quot;5. Аналитика&quot;">​</a></h3><p>Глубокий анализ совокупного капитала, структуры активов и распределения расходов:</p><ul><li><strong>Динамика чистого капитала:</strong> помесячный график роста богатства с гарантией сохранения истории удаленных мастерских.</li><li><strong>Структура распределения активов:</strong> соотношение свободных денег, мастерских, личных вещей и инвестиций.</li><li><strong>Тренды свободных расходов:</strong> автоматический расчет повседневных расходов на жизнь.</li><li><strong>Стартовая заглушка:</strong> при отсутствии данных вкладка встречает аккуратным экраном первичного входа со ссылкой на добавление первого счета и кнопкой запуска демонстрационного режима.</li><li><strong>🛡️ Непрерывность истории и срезы удалённых пространств (Этап M5):</strong> при ликвидации или окончательном удалении ненужного бизнес-пространства его файл операционной базы данных безопасно очищается с диска, но система автоматически сохраняет в глобальном реестре компактный помесячный статистический срез (выручка, себестоимость, расходы, амортизация и капитал). Это гарантирует, что ретроспективный график динамики чистых активов в «Моём капитале» никогда не получит провалов и искажений за прошлые периоды, сохраняя полную финансовую историю мастера.</li></ul><hr><h2 id="сквозные-тематические-модули" tabindex="-1">Сквозные тематические модули <a class="header-anchor" href="#сквозные-тематические-модули" aria-label="Permalink to &quot;Сквозные тематические модули&quot;">​</a></h2><p>В будущем в нижней секции выдвижной шторки будут появляться <strong>Сквозные модули</strong> — нишевые инструменты, которые можно докупать отдельно.</p><p>Они называются «сквозными», потому что <strong>не привязаны к конкретной базе данных</strong>. Например, модуль «Амбассадор» доступен вам из любого активного рабочего пространства, позволяя вести продвижение и управлять партнерскими кампаниями для всех ваших направлений бизнеса.</p><p>Управление модулями и их статусом также централизовано в боковой шторке и привязано к вашему единому лицензионному ключу, который «эволюционирует» по мере расширения вашей экосистемы.</p><hr><h2 id="разбор-внештатных-ситуации-troubleshooting" tabindex="-1">Разбор внештатных ситуаций (Troubleshooting) <a class="header-anchor" href="#разбор-внештатных-ситуации-troubleshooting" aria-label="Permalink to &quot;Разбор внештатных ситуаций (Troubleshooting)&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если при нажатии на кнопку пространств боковая шторка не выезжает?</summary><div class="faq-content"><p>Убедитесь, что в программе активирована лицензия ПРО: на стандартных тарифах доступно только одно рабочее пространство, а кнопка шторки не отображается. Проверьте статус ключа в глобальных «Настройках программы».</p></div></details><details class="faq-item"><summary class="faq-summary">Как создать резервную копию всех рабочих мастерских сразу?</summary><div class="faq-content"><p>Откройте правую боковую шторку и нажмите кнопку «Единый бэкап системы». ОмниКрафт ЕРП сформирует общий защищенный архив, содержащий базу «Моего капитала» и базы данных всех зарегистрированных пространств.</p></div></details><details class="faq-item"><summary class="faq-summary">Исказятся ли графики прошлых периодов при ликвидации одного из направлений?</summary><div class="faq-content"><p>Нет. При окончательном удалении пространства программа сохраняет в глобальном реестре компактный ежемесячный статистический срез показателей. Графики динамики чистого капитала за прошлые годы сохраняют абсолютную непрерывность.</p></div></details></div>',59))])}const v=a(c,[["render",g]]);export{x as __pageData,v as default};
